import {esc,icon,panelHeader} from './ui.js';
import {platform} from './server-api.js';
export function realSync(ui){const busy=ui.serverBusy;return`${panelHeader('IMPORT YOUR SOURCES','导入真实资料')}<div class="panel-content"><div class="notice">原文保存在你的服务器。点击分析时，选定资料会发送到服务器配置的模型接口；模型结果需审阅后才能更新能力树。</div>${!platform.aiReady?'<div class="notice warning">模型接口尚未配置。可以先保存原始资料，配置后再分析。</div>':''}<label class="field-label" for="source-title-input">资料名称</label><input class="wide-select" id="source-title-input" maxlength="160" value="${esc(ui.sourceTitle||'')}" placeholder="例如：后端学习记录.md" ${busy?'disabled':''}><label class="field-label" for="source-file">读取本地 Markdown / 文本</label><input id="source-file" type="file" accept=".md,.txt,text/plain,text/markdown" ${busy?'disabled':''}><label class="field-label" for="source-body-input" style="margin-top:16px">或粘贴本次授权的资料</label><textarea class="source-input" id="source-body-input" maxlength="50000" placeholder="仅粘贴你决定导入的内容，10–50000 字符。" ${busy?'disabled':''}>${esc(ui.sourceBody||'')}</textarea><button class="primary-button wide" data-server-action="save-source" ${busy?'disabled':''}>${busy?'正在处理，请稍候…':'保存原文到服务器'}</button>${ui.serverError?`<div class="answer-feedback incorrect">${esc(ui.serverError)}</div>`:''}${ui.serverSource?`<article class="source-card" style="margin-top:20px"><span class="tag">原文已保存</span><h4>${esc(ui.sourceTitle)}</h4><p>资料 ID：${esc(ui.serverSource)}</p><button class="outline-button" data-server-action="analyze" ${busy||!platform.aiReady?'disabled':''}>${busy?'模型分析中…':'授权发送本份资料并分析'}</button></article>`:''}${ui.serverPlan?`<div class="section-heading"><span>请审阅本次变更</span><small>${ui.serverPlan.changes?.length||0} 项</small></div>${(ui.serverPlan.changes||[]).map(c=>`<article class="change-row"><span class="change-type">${esc(c.type)}</span><div><h4>${esc(c.title)}</h4><p>${esc(c.detail||'补充来源与前置关系，保留已有内容。')}</p>${c.prerequisites?.length?`<p>前置：${c.prerequisites.map(esc).join('、')}</p>`:''}</div></article>`).join('')}<div class="notice">${esc(ui.serverPlan.notice||'能力等级与项目阶段不会自动提升。')}</div><button class="primary-button wide" data-server-action="apply" ${busy?'disabled':''}>确认应用，创建新版本</button>`:''}<div class="section-heading"><span>已保存的资料</span></div>${(ui.serverSources||[]).map(s=>`<article class="source-card"><h4>${esc(s.title)}</h4><button class="text-button" data-reanalyze="${s.id}" ${busy||!platform.aiReady?'disabled':''}>基于当前路线分析 ↗</button></article>`).join('')||'<p class="muted">还没有资料。从一份小文档开始。</p>'}</div>`}
export function realMentor(n,ui){const answer=ui.mentor[n.id];return`<div class="notice">回答使用当前节点、目标及其关联来源。点击发送后，这些内容会发送到已配置的模型接口。</div><label class="field-label" for="mentor-question">围绕这个节点继续问</label><textarea class="source-input" id="mentor-question" maxlength="2000" placeholder="例如：结合项目解释这个知识，并给我两个练习步骤。">${esc(ui.mentorQuestion||'')}</textarea><button class="primary-button wide" data-server-action="mentor" ${ui.serverBusy||!platform.aiReady||ui.version!==null?'disabled':''}>${ui.serverBusy?'正在请求导师…':'发送问题'}</button>${!platform.aiReady?'<p class="muted">请先在服务器配置模型接口。</p>':''}${ui.version!==null?'<p class="muted">历史快照只读，请返回当前路线后向导师提问。</p>':''}${ui.serverError?`<div class="answer-feedback incorrect">${esc(ui.serverError)}</div>`:''}${answer?.answer?`<article class="mentor-answer"><span class="overline">AI 导师 · 需结合来源核对</span><p style="white-space:pre-wrap">${esc(answer.answer)}</p>${answer.sources.map(s=>`<button class="source-link" data-source="${s.id}">${icon('source')}${esc(s.title)} ↗</button>`).join('')}</article>`:''}`}
export function realGoal(s,store){return`${panelHeader('YOUR GOAL','当前目标与项目')}<div class="panel-content"><label class="field-label" for="goal-text-input">长期学习目标</label><input class="wide-select" id="goal-text-input" maxlength="160" value="${esc(store.goalText||'')}"><label class="field-label" for="goal-select">关联目标项目</label><select class="wide-select" id="goal-select"><option value="">全部知识，先补基础</option>${s.nodes.filter(n=>n.kind==='project').map(n=>`<option value="${n.id}" ${store.target===n.id?'selected':''}>${esc(n.title)}</option>`).join('')}</select><button class="primary-button wide" data-server-action="goal">保存目标</button><div class="notice" style="margin-top:20px">能力树按前置关系与项目需求展示。讨论记录不等于独立掌握，先完成可验证的实践。</div></div>`}
export function realTasks(n,s,ui,store,taskKey){return`<p class="panel-intro">练习由导入资料分析产生。勾选只记录完成情况，不改变能力证据等级。</p>${n.tasks.map((t,i)=>`<label class="task-row"><input type="checkbox" data-task="${i}" ${store.tasks[taskKey(s.version,n.id,i)]?'checked':''} ${ui.version!==null?'disabled':''}><span>${esc(t)}</span></label>`).join('')}<div class="section-heading"><span>需注意的误区</span></div>${n.mistakes.map(([title,text])=>`<article class="mistake"><h3>${esc(title)}</h3><p>${esc(text)}</p></article>`).join('')}`}
